function PermissionNotice({ children }) { return <div className="permission-notice"><Icon name="warning" size={15}/><span>{children}</span></div> }

function mergeDeep(target, source) { const out = { ...(target || {}) }; Object.entries(source || {}).forEach(([key, value]) => { out[key] = value && typeof value === 'object' && !Array.isArray(value) ? mergeDeep(out[key], value) : value }); return out }
