function t(settings, key, fallback) { const lang = settings?.localization?.defaultLanguage || settings?.language || 'en'; const catalog = settings?.localization?.translations || {}; return catalog?.[lang]?.[key] || catalog?.[settings?.localization?.fallbackLanguage || 'en']?.[key] || (fallback ? translateUiText(settings, fallback) : key) }
function enabledPages(settings) { const order = Array.isArray(settings?.interface?.navigationOrder) && settings.interface.navigationOrder.length ? settings.interface.navigationOrder : (settings?.enabledPages || defaultSettings.enabledPages); const visibility = settings?.interface?.navigationVisibility || {}; return order.filter(page => defaultSettings.enabledPages.includes(page) && visibility[page] !== false && settings?.modules?.[page]?.enabled !== false) }
