  const visibility = form.interface?.navigationVisibility || {}
  const order = [...new Set([...(form.interface?.navigationOrder || pages), ...pages])].filter(page => pages.includes(page))
  const [drag, setDrag] = useState('')
  const apply = (nextOrder = order, nextVisibility = visibility, nextModules = form.modules || {}) => { patch('interface.navigationOrder', nextOrder); patch('interface.navigationVisibility', nextVisibility); patch('modules', nextModules); patch('enabledPages', nextOrder.filter(page => nextVisibility[page] !== false && nextModules?.[page]?.enabled !== false)) }
  const move = (key, direction) => { const index = order.indexOf(key); const target = index + direction; if (target < 0 || target >= order.length) return; const next = [...order]; [next[index], next[target]] = [next[target], next[index]]; apply(next) }
  const drop = key => { if (!drag || drag === key) return; const next = order.filter(page => page !== drag); next.splice(next.indexOf(key), 0, drag); apply(next); setDrag('') }
  const toggle = (key, checked) => apply(order, { ...visibility, [key]: checked }, { ...(form.modules || {}), [key]: { ...((form.modules || {})[key] || {}), enabled: checked } })
