  const updateStates = nextStates => setWorkflow({ ...workflow, states: nextStates, transitions: transitions.filter(t => nextStates.some(s => s.label === t.from) && nextStates.some(s => s.label === t.to)) })
  const updateState = (index, row) => updateStates(states.map((state, i) => i === index ? { ...state, ...row, id: row.label ? slug(row.label) : state.id } : state))
  const moveState = (index, direction) => { const target = index + direction; if (target < 0 || target >= states.length) return; const next = [...states]; [next[index], next[target]] = [next[target], next[index]]; updateStates(next) }
  const addState = () => { if (!newState.trim()) return; updateStates([...states, { id: slug(newState), label: newState.trim(), color: 'blue', terminal: false }]); setNewState('') }
  const addTransition = () => states.length > 1 && setWorkflow({ ...workflow, transitions: [...transitions, { from: states[0].label, to: states[1].label, permission: 'writeTasks', approvalRequired: false }] })
  const updateTransition = (index, row) => setWorkflow({ ...workflow, transitions: transitions.map((transition, i) => i === index ? { ...transition, ...row } : transition) })
